mapper.delete:
DELETE FROM ${tableName}
WHERE enterprise_code = #{currentEnterpriseCode}
AND primary_key = #{templateCode}
AND delete_flag = 'f'

    ${dataScopeParams.dataScope}

mapper.select:
SELECT COUNT(id)
FROM ${tableName}
WHERE enterprise_code = #{currentEnterpriseCode}
  AND sell_template_belong = #{userCode}
  AND primary_key != #{templateCode}
  AND template_name = #{templateName}
  AND delete_flag = 'f'

SELECT primary_key as templateCode, template_name, type, order_value, sell_template_belong as userCode, user_name, state, data_version, create_time, update_time, delete_flag FROM ${tableName} WHERE enterprise_code= #{currentEnterpriseCode} AND delete_flag= 'f'
AND template_name LIKE '%'|| #{templateName} ||'%'
AND type = #{type}
AND state = #{state}
${dataScopeParams.dataScope}
ORDER BY order_value DESC,create_time DESC

SELECT primary_key as templateCode, template_name, type, order_value, buyer, seller, enterprise_code as ownedEnterpriseCode, sell_template_belong as userCode, user_name, language, payment_strategy, product_grade, column_titles, amount_title, state, clauses_chs, clauses_en, temp_data, data_version, create_time, update_time, delete_flag FROM ${tableName} WHERE enterprise_code= #{currentEnterpriseCode} AND primary_key = #{templateCode}
${dataScopeParams.dataScope}
AND delete_flag= 'f'

mapper.update:
UPDATE ${tableName}
SET order_value = #{model.orderValue},
data_version = #{model.dataVersion}
WHERE
enterprise_code= #{model.ownedEnterpriseCode}
AND primary_key = #{model.templateCode}

    ${dataScopeParams.dataScope}

AND data_version = #{clientDataVersion}
AND delete_flag= 'f'

UPDATE ${tableName}
SET temp_data = #{model.tempData}
WHERE
enterprise_code= #{model.ownedEnterpriseCode}
AND primary_key = #{model.templateCode}

    ${dataScopeParams.dataScope}

UPDATE ${tableName}
SET temp_data = NULL
WHERE
enterprise_code= #{model.ownedEnterpriseCode}
AND primary_key = #{model.templateCode}
AND temp_data IS NOT NULL

    ${dataScopeParams.dataScope}

UPDATE ${tableName} SET template_name = #{model.templateName}, buyer = #{model.buyer}, seller = #{model.seller}, language = #{model.language}, payment_strategy = #{model.paymentStrategy}, product_grade = #{model.productGrade}, column_titles = #{model.columnTitles}, amount_title = #{model.amountTitle}, clauses_chs = #{model.clausesChs}, clauses_en = #{model.clausesEn}, state = #{model.state}, temp_data = null, data_version = #{model.dataVersion}, delete_flag = 'f' WHERE enterprise_code= #{model.ownedEnterpriseCode} AND primary_key = #{model.templateCode}
${dataScopeParams.dataScope}
AND data_version = #{clientDataVersion}
